import numpy as np
def comps(D):
    D=np.array(D); H,W=D.shape; seen=np.zeros_like(D,bool); out=[]
    for r in range(H):
        for c in range(W):
            if D[r,c]!=0 and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and D[x,y]!=0 and not seen[x,y]:
                            seen[x,y]=True; st.append((x,y))
                out.append(comp)
    return out

