# Hypothesis H6: a 2 is "anchored" if another 2 shares its row or column; anchored 2s don't trigger recoloring.
def solve(gin):
    g=[row[:] for row in gin]; H=len(g); W=len(g[0])
    twos=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    anchored=set()
    for (r,c) in twos:
        if any(q==r or p==c for q,p in twos if (q,p)!=(r,c)): anchored.add((r,c))
    out=[r[:] for r in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=3: continue
            hits=[(ra,cb) for ra in(-1,0,1) for cb in(-1,0,1) if (ra,cb)!=(0,0) and 0<=r+ra<H and 0<=c+cb<W and g[r+ra][c+cb]==2]
            rec=sum(1 for ra,cb in hits if (r+ra,c+cb) not in anchored)
            out[r][c]=1 if rec>0 else g[r][c]
    return out
